-- name: ApmLatestExceptionEventOfIssue :one
-- The most recent occurrence's full stacktrace: the issue detail view's "latest example".
SELECT * FROM apm_exception_events
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id') AND issue_id = sqlc.arg('issue_id')
ORDER BY created_at DESC
LIMIT 1;

-- name: DeleteOldApmExceptionEventsSystem :execrows
-- System scope, the retention sweep: drops exception events older than 30 days, across every team.
DELETE FROM apm_exception_events WHERE created_at < sqlc.arg('before');
